def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_d = 0
    opp_d = 0
    recent_opp_d = 0
    for i in range(n):
        mine, opp = history[i]
        if mine == 'D':
            my_d += 1
        if opp == 'D':
            opp_d += 1
            if i >= n - 10:
                recent_opp_d += 1

    after_d_c = 0
    after_d_d = 0
    for i in range(1, n):
        prev_mine = history[i - 1][0]
        cur_opp = history[i][1]
        if prev_mine == 'D':
            if cur_opp == 'C':
                after_d_c += 1
            else:
                after_d_d += 1

    last_my, last_opp = history[-1]
    prev2_my = history[-2][0] if n >= 2 else 'C'

    if opp_d == n or recent_opp_d >= 6:
        return 'D'
    if n >= 5 and opp_d * 3 >= n * 2:
        return 'D'
    if n >= 8 and opp_d * 2 >= n:
        return 'D'

    if opp_d == 0:
        if n <= 3:
            return 'C'
        if my_d == 0:
            return 'D'
        if n >= 16 and after_d_c >= 5:
            return 'D'
        if n >= 98:
            return 'D'
        if last_my == 'D':
            return 'C'
        return 'D'

    if last_opp == 'C' and recent_opp_d == 0 and opp_d <= max(1, n // 10):
        if my_d == 0:
            if n >= 4:
                return 'D'
        elif after_d_d == 0:
            if n >= 20 and after_d_c >= 5:
                return 'D'
            return 'D' if last_my == 'C' else 'C'

    if last_opp == 'D':
        if prev2_my == 'D':
            if recent_opp_d <= 2 and opp_d <= max(4, n // 2):
                return 'C'
            if recent_opp_d <= 3 and opp_d * 3 <= n:
                return 'C'
            return 'D'
        return 'D'

    if recent_opp_d >= 4 and opp_d * 3 > n:
        return 'D'

    return 'C'
